<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/VendorRelationshipClaim.php';Security::start();$pdo=Db::pdo();$csrf=Security::csrf();
$vendors=$pdo->query("SELECT id,name FROM vendors WHERE status='active' ORDER BY name LIMIT 300")->fetchAll(PDO::FETCH_ASSOC);
$products=$pdo->query("SELECT id,name FROM products WHERE status='active' ORDER BY name LIMIT 500")->fetchAll(PDO::FETCH_ASSOC);
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add existing software to company portfolio | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f7fafc;color:#1f2937}.wrap{max-width:900px;margin:36px auto;padding:0 20px}.card{background:#fff;border:1px solid #dce6ed;border-radius:16px;padding:24px}label{display:block;font-weight:700;margin:14px 0 6px}select,input,textarea{width:100%;padding:11px;border:1px solid #cfdbe3;border-radius:9px;box-sizing:border-box}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.note{color:#64748b;font-size:13px;line-height:1.6}.territory{display:grid;grid-template-columns:150px 150px 1fr;gap:8px;margin:8px 0}button{margin-top:18px;padding:11px 16px;border:0;border-radius:9px;background:#123b67;color:#fff;font-weight:750}.result{margin-top:14px}.warn{background:#fff8e8;padding:12px;border-radius:10px}@media(max-width:650px){.grid,.territory{grid-template-columns:1fr}}</style></head><body><main class="wrap"><div class="card"><h1>Add existing software to company portfolio</h1><p class="note">Use this when a company resells, distributes, implements, refers or locally represents software already listed on TechSelectAI. This does <strong>not</strong> grant software ownership. The relationship is not shown as verified until TechSelectAI reviews supporting evidence.</p><form id="claim"><div class="grid"><div><label>Company</label><select name="vendor_id" required><option value="">Select company</option><?php foreach($vendors as $v):?><option value="<?=$v['id']?>"><?=$esc($v['name'])?></option><?php endforeach?></select></div><div><label>Existing software</label><select name="product_id" required><option value="">Select software</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=$esc($p['name'])?></option><?php endforeach?></select></div></div><label>Relationship type</label><select name="relationship_type" required><?php foreach(VendorRelationshipClaim::RELATIONSHIPS as $r):?><option value="<?=$r?>"><?=$esc(ucwords(str_replace('_',' ',$r)))?></option><?php endforeach?></select><label>Territories</label><div id="territories"><div class="territory"><select class="tt"><option value="country">Country</option><option value="region">Region</option><option value="global">Global</option></select><input class="tc" placeholder="Code, e.g. SA / GCC / GLOBAL" required><input class="tn" placeholder="Name, e.g. Saudi Arabia" required></div></div><button type="button" id="addTerritory" style="background:#475569">+ Add territory</button><div class="grid"><div><label>Evidence type</label><select name="evidence_type"><?php foreach(VendorRelationshipClaim::EVIDENCE_TYPES as $e):?><option value="<?=$e?>"><?=$esc(ucwords(str_replace('_',' ',$e)))?></option><?php endforeach?></select></div><div><label>Company email</label><input name="submitter_email" type="email" required></div></div><label>Evidence URL</label><input name="evidence_url" type="url" placeholder="Official manufacturer partner directory or company-domain evidence"><label>Agreement/reference</label><input name="evidence_reference" placeholder="Reference number or document identifier"><label>Evidence notes</label><textarea name="evidence_note" rows="4"></textarea><div class="grid"><div><label>Valid from</label><input name="valid_from" type="date"></div><div><label>Valid until</label><input name="valid_until" type="date"></div></div><p class="note">Territory is mandatory. Claims may be pending, verified, rejected, expired or revoked. Time-limited authorization should include a validity end date.</p><button>Submit relationship claim</button><div id="result" class="result"></div></form></div></main><script>const csrf=<?php echo json_encode($csrf)?>;document.getElementById('addTerritory').onclick=()=>{const d=document.querySelector('.territory').cloneNode(true);d.querySelectorAll('input').forEach(i=>i.value='');document.getElementById('territories').appendChild(d)};document.getElementById('claim').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),territories=[...document.querySelectorAll('.territory')].map(r=>({type:r.querySelector('.tt').value,code:r.querySelector('.tc').value,name:r.querySelector('.tn').value}));const body=Object.fromEntries(f.entries());body.territories=territories;const res=await fetch('/api/vendor-relationship-claims',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});const j=await res.json();const out=document.getElementById('result');if(!res.ok){out.innerHTML='<div class="warn">'+String(j.error||'Submission failed')+'</div>';return}out.innerHTML=j.duplicate?'<div class="warn">An active claim for the same company, software, relationship and territories already exists (#'+j.id+').</div>':'<div class="warn">Claim #'+j.id+' submitted for review. It is not publicly verified yet.</div>';};</script></body></html>